package care.tend.goal;
import care.tend.common.CurrentUser;import care.tend.item.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;import java.util.*;
@RestController@RequestMapping("/api/goals")public class GoalProgressController{private final JdbcTemplate jdbc;private final LifeItemRepository items;public GoalProgressController(JdbcTemplate jdbc,LifeItemRepository items){this.jdbc=jdbc;this.items=items;}public record Milestone(UUID id,String title,boolean completed,int sortOrder,Instant completedAt){}public record MilestoneRequest(@NotBlank@Size(max=200)String title){}public record ProgressRequest(@PositiveOrZero BigDecimal value,@Size(max=2000)String note){}public record Progress(UUID id,BigDecimal value,String note,String source,Instant recordedAt){}public record Detail(List<Milestone>milestones,List<Progress>history,double calculatedPercent){}
 @GetMapping("/{id}/progress")Detail detail(@PathVariable UUID id){var uid=owner(id);var ms=jdbc.query("select id,title,completed,sort_order,completed_at from goal_milestone where user_id=? and goal_id=? order by sort_order,created_at",(rs,n)->new Milestone(rs.getObject(1,UUID.class),rs.getString(2),rs.getBoolean(3),rs.getInt(4),rs.getTimestamp(5)==null?null:rs.getTimestamp(5).toInstant()),uid,id);var hs=jdbc.query("select id,value,note,source,recorded_at from goal_progress where user_id=? and goal_id=? order by recorded_at desc",(rs,n)->new Progress(rs.getObject(1,UUID.class),rs.getBigDecimal(2),rs.getString(3),rs.getString(4),rs.getTimestamp(5).toInstant()),uid,id);double pct=ms.isEmpty()?hs.stream().findFirst().map(p->p.value()==null?0.0:p.value().doubleValue()).orElse(0.0):ms.stream().filter(Milestone::completed).count()*100.0/ms.size();return new Detail(ms,hs,Math.round(pct*10)/10.0);}
 @PostMapping("/{id}/milestones")@ResponseStatus(HttpStatus.CREATED)Milestone milestone(@PathVariable UUID id,@Valid@RequestBody MilestoneRequest r){var uid=owner(id);return jdbc.queryForObject("insert into goal_milestone(user_id,goal_id,title,sort_order) values (?,?,?,(select count(*) from goal_milestone where goal_id=?)) returning id,title,completed,sort_order,completed_at",(rs,n)->new Milestone(rs.getObject(1,UUID.class),rs.getString(2),rs.getBoolean(3),rs.getInt(4),null),uid,id,r.title(),id);}
 @PatchMapping("/{goalId}/milestones/{milestoneId}")Milestone toggle(@PathVariable UUID goalId,@PathVariable UUID milestoneId){var uid=owner(goalId);return jdbc.queryForObject("update goal_milestone set completed=not completed,completed_at=case when not completed then now() else null end where id=? and goal_id=? and user_id=? returning id,title,completed,sort_order,completed_at",(rs,n)->new Milestone(rs.getObject(1,UUID.class),rs.getString(2),rs.getBoolean(3),rs.getInt(4),rs.getTimestamp(5)==null?null:rs.getTimestamp(5).toInstant()),milestoneId,goalId,uid);}
 @PostMapping("/{id}/progress")@ResponseStatus(HttpStatus.CREATED)@Transactional Progress record(@PathVariable UUID id,@Valid@RequestBody ProgressRequest r){var uid=owner(id);var goal=items.findByIdAndUserId(id,uid).orElseThrow();if(r.value()!=null)goal.progressValue=r.value();items.save(goal);return jdbc.queryForObject("insert into goal_progress(user_id,goal_id,value,note,source) values (?,?,?,?,'MANUAL') returning id,value,note,source,recorded_at",(rs,n)->new Progress(rs.getObject(1,UUID.class),rs.getBigDecimal(2),rs.getString(3),rs.getString(4),rs.getTimestamp(5).toInstant()),uid,id,r.value(),r.note());}
 private UUID owner(UUID id){var uid=CurrentUser.id();items.findByIdAndUserId(id,uid).filter(i->i.type==LifeItem.Type.GOAL).orElseThrow();return uid;}}
